function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw obstacles
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.rect(W/4, H/4, W/2, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(W/2, H/2, W/4, H/4);
  ctx.stroke();

  // draw water flow
  ctx.lineWidth = 2;
  ctx.strokeStyle = 'black';
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.moveTo(0, H/2 + Math.sin(t + i) * 20);
    ctx.bezierCurveTo(W/4 + Math.cos(t + i) * 20, H/2 + Math.sin(t + i) * 20, 
                       W/2 + Math.cos(t + i) * 10, H/2 + Math.sin(t + i) * 10, 
                       W, H/2 + Math.sin(t + i) * 10);
    ctx.stroke();
  }

  // draw tao symbol
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
